mapper.select:
SELECT id, biz_type, export_format, status, progress_percent, processed_rows, total_rows, file_record_id, error_code, retry_count, max_retry, started_at, finished_at, expire_at, created_at, updated_at, created_by, updated_by FROM file_export_task
created_by = #{createdBy}
AND biz_type = #{query.bizType}
AND status = #{query.status}
AND export_format = #{query.exportFormat}
AND created_at >= #{query.startTime} AND created_at <= #{query.endTime}
ORDER BY created_at DESC, id DESC

SELECT id, biz_type, export_format, status, progress_percent, processed_rows, total_rows, file_record_id, error_code, error_message, retry_count, max_retry, locked_by, lease_until, started_at, finished_at, expire_at, created_at, updated_at, created_by, updated_by FROM file_export_task
AND created_by = #{query.createdBy}
AND biz_type = #{query.bizType}
AND status = #{query.status}
AND export_format = #{query.exportFormat}
AND error_code = #{query.errorCode}
AND created_at >= #{query.startTime} AND created_at <= #{query.endTime}
ORDER BY created_at DESC, id DESC

SELECT id
FROM file_export_task
WHERE (
    status = 'PENDING'
        AND (
        next_retry_at IS NULL
            OR next_retry_at  <=  #{now}
        )
    )
   OR (
    status IN ('RUNNING', 'CANCELLING')
        AND lease_until IS NOT NULL
        AND lease_until  <  #{now}
    )
ORDER BY created_at
LIMIT #{limit}

mapper.update:
UPDATE file_export_task
SET status      = 'RUNNING',
    locked_by   = #{workerId},
    lease_until = #{leaseUntil},
    started_at  = IFNULL(started_at, #{now}),
    updated_at  = #{now}
WHERE id = #{id}
  AND (
    (
        status = 'PENDING'
            AND (
            next_retry_at IS NULL
                OR next_retry_at  <=  #{now}
            )
        )
        OR (
        status IN ('RUNNING', 'CANCELLING')
            AND lease_until IS NOT NULL
            AND lease_until  <  #{now}
        )
    )

UPDATE file_export_task
SET lease_until = #{leaseUntil},
    updated_at  = NOW(3)
WHERE id = #{id}
  AND status IN ('RUNNING', 'CANCELLING')
  AND locked_by = #{workerId}

UPDATE file_export_task SET status = 'CANCELLED', finished_at = #{now}, locked_by = NULL, lease_until = NULL, updated_at = #{now} WHERE id = #{id}
AND created_by = #{createdBy}
AND status = 'PENDING'

UPDATE file_export_task SET status = 'CANCELLING', updated_at = NOW(3) WHERE id = #{id}
AND created_by = #{createdBy}
AND status = 'RUNNING'

UPDATE file_export_task SET status = 'PENDING', retry_count = retry_count + 1, next_retry_at = NULL, error_code = NULL, error_message = NULL, progress_percent = 0, processed_rows = 0, total_rows = NULL, file_record_id = NULL, started_at = NULL, finished_at = NULL, locked_by = NULL, lease_until = NULL, updated_at = #{now} WHERE id = #{id}
AND created_by = #{createdBy}
AND status IN ('FAILED', 'CANCELLED') AND retry_count < max_retry

UPDATE file_export_task SET status = 'PENDING', retry_count = retry_count + 1, next_retry_at = NULL, error_code = NULL, error_message = NULL, progress_percent = 0, processed_rows = 0, total_rows = NULL, file_record_id = NULL, started_at = NULL, finished_at = NULL, locked_by = NULL, lease_until = NULL, updated_at = #{now} WHERE id = #{id}
AND created_by = #{createdBy}
AND status IN ('FAILED', 'CANCELLED')

UPDATE file_export_task
SET status        = 'CANCELLED',
    next_retry_at = NULL,
    finished_at   = #{now},
    locked_by     = NULL,
    lease_until   = NULL,
    updated_at    = #{now}
WHERE id = #{id}
  AND status IN ('RUNNING', 'CANCELLING')
  AND locked_by = #{workerId}

UPDATE file_export_task SET status = 'EXPIRED', file_record_id = NULL, next_retry_at = NULL, updated_at = #{now} WHERE status = 'SUCCESS' AND (
(id = #{task.id} AND file_record_id = #{task.fileRecordId})
)
